package com.amit.jobagent.application;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;
@Entity @Table(name="application_package_revision")class ApplicationPackageRevision{
 @Id UUID id;@Column(name="application_package_id",nullable=false,updatable=false)UUID packageId;@Column(name="revision_number",nullable=false,updatable=false)int revisionNumber;@Column(name="candidate_profile_version_id",nullable=false,updatable=false)UUID profileVersionId;@Column(name="job_evaluation_id",nullable=false,updatable=false)UUID evaluationId;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="source_job_checksum",nullable=false,updatable=false,length=64,columnDefinition="char(64)")String jobChecksum;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="source_profile_checksum",nullable=false,updatable=false,length=64,columnDefinition="char(64)")String profileChecksum;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="source_evaluation_checksum",nullable=false,updatable=false,length=64,columnDefinition="char(64)")String evaluationChecksum;@Column(name="generation_prompt_version",nullable=false,updatable=false,length=40)String promptVersion;@Column(name="generation_schema_version",nullable=false,updatable=false,length=40)String schemaVersion;@Column(name="template_version",nullable=false,updatable=false,length=40)String templateVersion;@Column(nullable=false,updatable=false,length=100)String model;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="generation_settings_checksum",nullable=false,updatable=false,length=64,columnDefinition="char(64)")String settingsChecksum;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="idempotency_key_hash",unique=true,length=64,columnDefinition="char(64)")String idempotencyKeyHash;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="generation_cache_key",nullable=false,unique=true,length=64,columnDefinition="char(64)")String cacheKey;@JdbcTypeCode(SqlTypes.JSON)@Column(name="generation_warnings",columnDefinition="jsonb",nullable=false)String warnings;@JdbcTypeCode(SqlTypes.JSON)@Column(name="unsupported_requirements",columnDefinition="jsonb",nullable=false)String unsupportedRequirements;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)RevisionStatus status;@Enumerated(EnumType.STRING)@Column(name="review_status",nullable=false,length=30)ReviewStatus reviewStatus;@Version@Column(name="review_record_version",nullable=false)long reviewRecordVersion;@Column(name="failure_code",length=80)String failureCode;@Column(name="failure_message",length=500)String failureMessage;@Column(name="created_at",nullable=false,updatable=false)Instant createdAt;@Column(name="completed_at")Instant completedAt;
 protected ApplicationPackageRevision(){}ApplicationPackageRevision(UUID pkg,int number,UUID profile,UUID evaluation,String jobHash,String profileHash,String evalHash,String prompt,String schema,String template,String model,String settings,String idempotency,String cache){id=UUID.randomUUID();packageId=pkg;revisionNumber=number;profileVersionId=profile;evaluationId=evaluation;jobChecksum=jobHash;profileChecksum=profileHash;evaluationChecksum=evalHash;promptVersion=prompt;schemaVersion=schema;templateVersion=template;this.model=model;settingsChecksum=settings;idempotencyKeyHash=idempotency;cacheKey=cache;warnings="[]";unsupportedRequirements="[]";status=RevisionStatus.REQUESTED;reviewStatus=ReviewStatus.NOT_READY;createdAt=Instant.now();}void status(RevisionStatus s){status=s;if(s!=RevisionStatus.READY)invalidateReview();}void retireCacheKey(String replacement){cacheKey=replacement;}void generationNotes(String warnings,String unsupported){this.warnings=warnings;unsupportedRequirements=unsupported;}void ready(){status=RevisionStatus.READY;reviewStatus=ReviewStatus.PENDING_REVIEW;completedAt=Instant.now();}void fail(String code,String message){status=RevisionStatus.FAILED;reviewStatus=ReviewStatus.NOT_READY;failureCode=code;failureMessage=message;completedAt=Instant.now();}void review(ReviewStatus value){reviewStatus=value;}void invalidateReview(){if(reviewStatus==ReviewStatus.APPROVED_FOR_HANDOFF)reviewStatus=ReviewStatus.INVALIDATED;}
}
